        SELECT 1 FROM pg_constraint c
        JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey)
        WHERE c.conrelid = to_regclass('bucket.access_logs') AND c.contype = 'f' AND a.attname = 'file_id'
    ) THEN
        ALTER TABLE bucket.access_logs ADD CONSTRAINT fk_access_logs_file_id FOREIGN KEY (file_id) REFERENCES bucket.stored_files (id) NOT VALID;
        BEGIN
            ALTER TABLE bucket.access_logs VALIDATE CONSTRAINT fk_access_logs_file_id;
        EXCEPTION WHEN foreign_key_violation THEN
            RAISE NOTICE 'fk_access_logs_file_id left NOT VALID: stored rows of bucket.access_logs reference missing rows';
        END;
    END IF;
END $$;

